class N:
    def __init__(s, k): s.k, s.l, s.r = k, None, None
def ins(t, k):
    if t is None: return N(k)
    if k < t.k: t.l = ins(t.l, k)
    else: t.r = ins(t.r, k)
    return t
def dele(t, k):
    if t is None: return None
    if k < t.k: t.l = dele(t.l, k)
    elif k > t.k: t.r = dele(t.r, k)
    elif t.l is None: return t.r          # leaf or only a right child
    elif t.r is None: return t.l          # only a left child
    else:
        s = t.r
        while s.l: s = s.l                # inorder successor
        t.k = s.k
        t.r = dele(t.r, s.k)
    return t
def level(t, d):
    return [] if t is None else ([t.k] if d == 0 else level(t.l, d - 1) + level(t.r, d - 1))
